// @vitest-environment node
// Type-checks the files generated by `init` in fixture projects: React (shadcn + plain)
// with `tsc --noEmit`, Vue SFCs with `vue-tsc --noEmit` (taken from the examples/vue-app
// workspace; the test is skipped when it is not installed). Package imports resolve to
// this package's src/ through tsconfig `paths`, dependencies through a node_modules symlink.
import { afterAll, describe, expect, it } from 'vitest'
import { execFileSync } from 'node:child_process'
import { existsSync, rmSync, symlinkSync } from 'node:fs'
import { createRequire } from 'node:module'
import { dirname, join, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'
import process from 'node:process'
import { runInit } from './init.js'
import { findTemplatesDir } from './main.js'
import { createFixture, writeFiles, type FixtureKind } from './test-fixtures.js'

const here = dirname(fileURLToPath(import.meta.url))
const packageDir = resolve(here, '../..')
const repoDir = resolve(packageDir, '../..')
const require = createRequire(import.meta.url)

const tscBin = require.resolve('typescript/bin/tsc')

function resolveVueTsc(): string | null {
  try {
    const req = createRequire(join(repoDir, 'examples/vue-app/package.json'))
    return req.resolve('vue-tsc/bin/vue-tsc.js')
  } catch {
    return null
  }
}
const vueTscBin = resolveVueTsc()

const roots: string[] = []
afterAll(() => {
  for (const root of roots) rmSync(root, { recursive: true, force: true })
})

const ENV_DTS = `interface ImportMetaEnv {
  readonly VITE_API_BASE_URL: string
}
interface ImportMeta {
  readonly env: ImportMetaEnv
}
`

const SONNER_STUB = `export const toast = {
  error(message: string, options?: { description?: string }): void {
    void message
    void options
  },
}
`

function prepare(kind: FixtureKind, sonner: boolean): string {
  const root = createFixture(kind, { sonner })
  roots.push(root)
  runInit({ cwd: root, dryRun: false, force: false, templatesDir: findTemplatesDir() })
  symlinkSync(join(packageDir, 'node_modules'), join(root, 'node_modules'), 'dir')

  const appDir = kind === 'vue' ? 'src' : 'app'
  const alias = kind === 'vue' ? '@/*' : '~/*'
  const paths: Record<string, string[]> = {
    [alias]: [`./${appDir}/*`],
    '@musikhood-dev/auth-client': [join(packageDir, 'src/index.ts')],
    '@musikhood-dev/auth-client/react': [join(packageDir, 'src/react.ts')],
    '@musikhood-dev/auth-client/vue': [join(packageDir, 'src/vue.ts')],
    sonner: ['./stubs/sonner.ts'],
  }
  writeFiles(root, {
    'env.d.ts': ENV_DTS,
    'stubs/sonner.ts': SONNER_STUB,
    'tsconfig.check.json': JSON.stringify(
      {
        compilerOptions: {
          target: 'ES2022',
          module: 'ESNext',
          moduleResolution: 'Bundler',
          lib: ['ES2022', 'DOM', 'DOM.Iterable'],
          jsx: kind === 'vue' ? 'preserve' : 'react-jsx',
          strict: true,
          noEmit: true,
          skipLibCheck: true,
          isolatedModules: true,
          verbatimModuleSyntax: true,
          types: [],
          baseUrl: '.',
          paths,
        },
        include: ['env.d.ts', `${appDir}/**/*.ts`, `${appDir}/**/*.tsx`, `${appDir}/**/*.vue`],
      },
      null,
      2,
    ),
  })
  return root
}

function typecheck(bin: string, root: string): string {
  try {
    execFileSync(process.execPath, [bin, '--noEmit', '-p', 'tsconfig.check.json'], {
      cwd: root,
      encoding: 'utf8',
      stdio: 'pipe',
    })
    return ''
  } catch (error) {
    const e = error as { stdout?: string; stderr?: string; message: string }
    return `${e.stdout ?? ''}${e.stderr ?? ''}` || e.message
  }
}

describe('wygenerowane pliki się kompilują', () => {
  it('React Router 7 + shadcn (+ sonner)', () => {
    const root = prepare('react-shadcn', true)
    expect(existsSync(join(root, 'app/routes/login/login.tsx'))).toBe(true)
    expect(typecheck(tscBin, root)).toBe('')
  }, 120_000)

  it('React Router 7 bez shadcn (plain, bez toastu)', () => {
    const root = prepare('react-plain', false)
    expect(typecheck(tscBin, root)).toBe('')
  }, 120_000)

  it.skipIf(vueTscBin === null)(
    'Vue 3 (vue-tsc)',
    () => {
      const root = prepare('vue', false)
      expect(typecheck(vueTscBin as string, root)).toBe('')
    },
    120_000,
  )
})
